def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    # Iterate through possible starting positions of the prefix in s
    for i in range(len(s) - len(prefix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check if the remaining part after prefix can accommodate the suffix
            remaining_length = len(s) - (i + len(prefix))
            if remaining_length >= len(suffix):
                if s[i + len(prefix):i + len(prefix) + len(suffix)] == suffix:
                    return True
            else:
                if s[i + len(prefix):] == suffix:
                    return True
    return False

