from math import gcd


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def maxLength(nums: List[int]) -> int:
    n = len(nums)
    max_len = 0

    for start in range(n):
        prod = 1
        g = nums[start]
        l = nums[start]
        for end in range(start, n):
            prod *= nums[end]
            g = gcd(g, nums[end])
            l = lcm(l, nums[end])
            if prod == l * g:
                max_len = max(max_len, end - start + 1)

    return max_len

