def maxAdjacentDistance(nums: List[int]) -> int:
    n = len(nums)
    max_distance = 0
    for i in range(n):
        # Calculate the absolute difference between current and next (circular)
        distance = abs(nums[i] - nums[(i + 1) % n])
        if distance > max_distance:
            max_distance = distance
    return max_distance

from collections import Counter

def findValidPair(s: str) -> str:
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            if counts[s[i]] == int(s[i]) and counts[s[i + 1]] == int(s[i + 1]):
                return s[i] + s[i + 1]
    return ""

