def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [1] * n  # Initialize dp array where each position starts with a length of 1
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff1 = abs(nums[i] - nums[j])
            # Check all possible previous elements to see if they form a valid subsequence
            if dp[j] > 0:
                diff2 = abs(nums[j] - nums[j-1]) if j > 0 else float('inf')
                if diff1 >= diff2:
                    dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])  # Update the overall max_length

    return max_length

def calculateScore(s: str) -> int:
    score = 0
    marked = set()
    n = len(s)
    for i in range(n):
        if i in marked:
            continue
        mirror_char = chr(219 - ord(s[i]))  # mirror of s[i]
        for j in range(i - 1, -1, -1):
            if j in marked:
                continue
            if s[j] == mirror_char:
                marked.add(i)
                marked.add(j)
                score += i - j
                break
    return score

